"""11-18: Ireland, first pack (works up to 1959, and pilgrimage places for Irish writers already on the UK map). Books chosen with
the scoring rubric (sel/ie: the James Joyce Centre / Irish Times shortlist of 50 Irish novels, the Irish Times 100 best Irish books
of the 21st century, the NT2000 survey, prizes, Goodreads, the Leaving Certificate lists, Bokklubben and thegreatestbooks.org),
plus the user's additions (Synge, Roddy Doyle, The Islandman, The Tain, Boll's Irish Journal). Fictional or unnamed settings hang
on the real place the book is modelled on, or on the writer's own place, and the note says which.
Gutenberg is down, so every book gets scene notes for now; the public-domain ones can take quotations later.
Coordinates come from Commons categories or geotagged Commons photos (coords_ie.json).
Usage: python3 -I add_ie1.py <app_dir> <coords_ie.json>"""
import json, os, sys
sys.path.insert(0, __file__.rsplit("/", 2)[0])
import batchlib as b
APP, CO = sys.argv[1], json.load(open(sys.argv[2], encoding="utf-8"))
b.init(APP, "", "ie", "2026-11-18")
W = b.W

def BK(id, title, title_zh, author, author_zh, year, pd=True, **kw):
    d = dict(id=id, title=title, title_zh=title_zh, author=author, author_zh=author_zh, year=year,
             orig_lang=kw.pop("lang", "en"), public_domain=pd, source_url=None)
    d.update(kw)
    return d

def C(pid):
    c = CO[pid]
    return c["lat"], c["lon"], c["st"], c["su"]

def ORIG(pid, name, zh, en_note, zh_note, **kw): return b.ORIG(pid, name, zh, *C(pid), en_note, zh_note, **kw)
def PROTO(pid, name, zh, en_note, zh_note, **kw): return b.PROTO(pid, name, zh, *C(pid), en_note, zh_note, **kw)
def PIL(pid, name, zh, en_note, zh_note, ids, **kw): return b.PIL(pid, name, zh, *C(pid), en_note, zh_note, ids, **kw)
